        float sim_best = 0;

        for (server_slot & slot : slots) {
            if (task.id_slot != -1 && slot.id != task.id_slot) continue;
            if (slot.is_processing()) continue;

            const auto & tokens = slot.prompt.tokens;
            if (tokens.empty()) continue;

            // fraction of the Longest Common Prefix length with respect to the input prompt length
            const float sim_cur = float(tokens.get_common_prefix(task.tokens)) / task.tokens.size();

            if (sim_cur > sim_best && sim_cur > slot_prompt_similarity) {
                sim_best = sim_cur;
                ret = &slot;
            }
        }

        if (ret != nullptr) {
            const float f_keep = (sim_best*task.tokens.size()) / ret->prompt.tokens.size();

            SLT_INF(*ret, "selected slot by LCP similarity, sim_best = %.3f (> %.3f thold), f_keep = %.3f\n",
                    sim_best, slot_prompt_similarity, f_keep);

            // if we are about to lose a large portion of the existing context - save it in the prompt cache
            if (f_keep < 0.5f) {
                update_cache = true;
            }
        }
    }

    // find the slot that has been least recently used
    if (ret == nullptr) {
        int64_t t_last = -1;
        for (server_slot & slot : slots) {
            if (slot.is_processing()) continue;
            if (!ret || slot.t_last_used <= t_last) {
                t_last = slot.t_last_used;
                ret = &slot;
            }
        }
        if (ret != nullptr) {
            SLT_INF(*ret, "selected slot by LRU, t_last = %" PRId64 "\n", t_last);
            update_cache = true;
        }
    }

    if (ret) {
        update_cache = update_cache && prompt_cache;
        update_cache = update_cache && task.type == SERVER_TASK_TYPE_COMPLETION;

        if (update_cache) {
            ret->prompt_save(*prompt_cache);
            if (!ret->prompt_load(*prompt_cache, task.tokens)) {
                ret->prompt_clear(false);
            }
            prompt_cache->update();
        }
    }

    return ret;
}
```

Key points:
- **`slot_prompt_similarity`** is a threshold (default 0.0, meaning disabled; set via `--slot-prompt-similarity`). When enabled, it picks the slot whose cached prompt shares the longest common prefix with the incoming request.
- `sim_cur = lcp_len / task.tokens.size()` — the fraction of the *new* prompt that is already cached in the slot.
- If the slot's existing prompt would be mostly discarded (`f_keep < 0.5`), the slot's KV state is **saved** into the global cache before being overwritten.

